*/
scwin.init_datefmt_cal_efReqEndDt = function () { $c.date.checkCalendarFormat("cal_efReqEndDt", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $("#fileUpload").change(function() {
                const files = this.files;
                if (files && files.length > 0) {
                    for (let i = 0; i < files.length; i++) {
                        const file = files[i];
                        scwin.appendFile(file);
                    }
                }
                $(this).val('');
                scwin.fileInfoSection.setStyle("display", "");
        });
        $("#upd_fileInput").change(async function() {
                const files = this.files;
                if (files && files.length > 0) {
                    for (let i = 0; i < files.length; i++) {
                        if (!scwin.addedFiles.has(files[i].name)) {
                            scwin.addedFiles.add(files[i].name);
                            scwin.appendFile(files[i]);
                        } else {
                            await $c.win.alert("[" + files[i].name + "] 파일이 이미 추가되었습니다.");
                        }
                    }
                }
                $(this).val('');
                scwin.fileInfoSection.setStyle("display", "");
        });
        $("#saveBtn").click(async function() {
                if ($("#fileInfoTable tbody tr").length === 0) {
                    await $c.win.alert("파일을 선택해주세요.");
                    return false;
                }
                const current_time = dma_hiddenStore.get("areaNowTimer");
                if (current_time < "160000" && ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ISREAL" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ISREAL"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ISREAL" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ISREAL")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ISREAL" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ISREAL"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ISREAL" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ISREAL"))))) === "real1" || (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ISREAL" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ISREAL"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ISREAL" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ISREAL")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ISREAL" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ISREAL"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ISREAL" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ISREAL"))))) === "real2")) {
                    await $c.win.alert("16시 이후 업로드가 가능합니다.");
                    return;
                }
                if (await $c.win.confirm("업로드 하시겠습니까?")) {
                    scwin.reNames();
                    (document.SendForm || { elements: [] }).action = "/upload/uploadFile.do";
                    $c.util.getComponent('dma_searchListReq').set('method', "uploadKsdExcelFile");
                    const p = {}; p["method"] = $c.util.getComponent("dma_searchListReq").get("method"); p["isurCd"] = $c.util.getComponent("dma_searchListReq").get("isurCd"); p["fileInput"] = $c.util.getComponent("upd_fileInput").getValue(); p["efReqStartDt"] = $c.util.getComponent("cal_efReqStartDt").getValue(); p["efReqEndDt"] = $c.util.getComponent("cal_efReqEndDt").getValue(); $c.win.setPageFrameSrc($c.win.getFrame(), '/jldbnf41000/jldbnf41000.xml', p);
                }
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf41000.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldbnf41000: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.upd_fileInput = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_fileInput') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_fileInput"]');

scwin.dmenus = undefined; try { scwin.dmenus = /* sdd-asis-lifecycle:begin dmenus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */{
        "bmenu":9
        ,"mmenu":0
    }/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf41000' }); }

scwin.dropZone = undefined; try { scwin.dropZone = /* sdd-asis-lifecycle:begin dropZone — as-is 원문 본문(전환 이관 · 포팅 적용됨) */document.querySelector('.file-drop-zone')/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf41000' }); }

scwin.browseBtn = undefined; try { scwin.browseBtn = /* sdd-asis-lifecycle:begin browseBtn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.util.getComponent('browseBtn')/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf41000' }); }

scwin.addedFiles = undefined; try { scwin.addedFiles = /* sdd-asis-lifecycle:begin addedFiles — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Set()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf41000' }); }

scwin.removeFile = removeFile;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_datefmt_cal_efReqStartDt();
        scwin.init_datefmt_cal_efReqEndDt();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf41000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.div_21_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.div_21_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin div_21_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $('#fileUpload').click()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf41000.div_21_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_searchList_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_searchList_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_searchList_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.searchList()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf41000.btn_searchList_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/upload/uploadFile.do",
        ref: "dma_searchListReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf41000.tx_fn_searchList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.appendFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param file
 * @returns
 * @hidden N
*/
scwin.appendFile = function (file) {
    /* sdd-asis-lifecycle:begin appendFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.fileCounter++;
    const fileName = file.name;
    const fileSize = scwin.formatFileSize(file.size);
    const fileDate = new Date().toLocaleString();
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.name = "attachFiles";
    fileInput.id = "uploadFile" + scwin.fileCounter;
    fileInput.setStyle("display", "none");
    const dataTransfer = new DataTransfer();
    dataTransfer.items.add(file);
    fileInput.files = dataTransfer.files;
    $c.util.getComponent("fileInfoTable").appendChild(fileInput);
    const newRow = "<tr id='file" + scwin.fileCounter + "'>" + "<td>" + fileName + "<input type='hidden' name='attach_file_tp_cd' value='29'></td>" + "<td>" + fileSize + "<input type='hidden' name='file_coment' value='예탁원파일'></td>" + "<td class='txc'><span id='' class='button small delete' onclick='removeFile(" + scwin.fileCounter + "); return false;'>삭제</span></td>" + "</tr>";
    $("#fileInfoTable tbody").append(newRow);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.formatFileSize
 * @author Inswave
 * @date 2026. 09. 29
 * @param bytes
 * @returns
 * @hidden N
*/
scwin.formatFileSize = function (bytes) {
    /* sdd-asis-lifecycle:begin formatFileSize — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (bytes === 0) {
        return '0 Bytes';
    }
    const k = 1024, sizes = ['Bytes', 'KB', 'MB', 'GB'], i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    /* sdd-asis-lifecycle:end */
};


function removeFile(id) {
    /* sdd-asis-lifecycle:begin removeFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fileInput = $c.util.getComponent("uploadFile" + id);
    if (fileInput) {
        fileInput.parentNode.removeChild(fileInput);
    }
    $("#file" + id).remove();
    if ($("#fileInfoTable tbody tr").length === 0) {

    }
    scwin.addedFiles.delete(fileInput.files[0].name);
    /* sdd-asis-lifecycle:end */
}

/**
 * @method
 * @name scwin.reNames
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reNames = function () {
    /* sdd-asis-lifecycle:begin reNames — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let nIdx = 0;
    $.each($("input:file"), function(i) {
            const _name = $(this).attr("name");
            if (_name === "fileInput") {
                $(this).value = "";
            } else {
                $(this).attr("name", "attachFiles[" + nIdx + "]");
                nIdx++;
            }
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.consoleLog
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.consoleLog = function () {
    /* sdd-asis-lifecycle:begin consoleLog — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    void("---------------------------------");
    scwin.addedFiles.forEach(function(item) {
            return void(item);
    });
    void("---------------------------------");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchList = async function () {
    /* sdd-asis-lifecycle:begin fn_searchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    fm.action = '/upload/uploadFile.do';
    $c.util.getComponent('dma_searchListReq').set('method', 'uploadForm');
    await scwin.tx_fn_searchList();
    /* sdd-asis-lifecycle:end */
};
